export function measureSocialText(text, font = 'sans') {
	const widths = SOCIAL_FONT_METRICS[font] || SOCIAL_FONT_METRICS.sans;
	return Array.from(String(text)).reduce((sum, char) => sum + (widths[char] ?? 0.65), 0);
}
